import{_ as e,o as l,c as r,a2 as i}from"./chunks/framework.DfDAiEgj.js";const t="/2bPM/img/pipei.png",o="/2bPM/img/dang.png",b=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"interview/question.md","filePath":"interview/question.md","lastUpdated":null}'),h={name:"interview/question.md"};function n(p,a,s,u,c,d){return l(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="如何验证学习效果" tabindex="-1">如何验证学习效果？ <a class="header-anchor" href="#如何验证学习效果" aria-label="Permalink to &quot;如何验证学习效果？&quot;">​</a></h2><p>给自己编30道面试题，对着镜子模拟面试，直到能得满分为止。再换下面的30道，这样一轮轮下来，遍历自己的认知边界。发现边界太窄，就继续扩张边界。</p><p>面试AI团队，最忌讳对AI认知过浅。咱们换位思考，假设你是面试官，遇到的求职者讲不清朴素贝叶斯、SVM、NLP瓶颈边界、神经网络类型和原理，不能深入分析某个AI场景......公司又不是慈善机构，凭什么给他工作机会？</p><h2 id="能力考察" tabindex="-1">能力考察 <a class="header-anchor" href="#能力考察" aria-label="Permalink to &quot;能力考察&quot;">​</a></h2><h3 id="管理能力" tabindex="-1">管理能力 <a class="header-anchor" href="#管理能力" aria-label="Permalink to &quot;管理能力&quot;">​</a></h3><p>管理能力主要看两方面:</p><p>(1)人际能力(团队内部的识人用人和激励能力，外部的协调能力); (2)决策能力(恰好也是产品经理的职业能力，只是除了市场权衡，还要进行内部人和事的权衡)。</p><h3 id="专业能力" tabindex="-1">专业能力 <a class="header-anchor" href="#专业能力" aria-label="Permalink to &quot;专业能力&quot;">​</a></h3><p>产品经理的专业能力，面试时一般从四个角度判断：</p><ol><li>批判性思维；</li><li>同理心（不要卖伤天害理的东西）；</li><li>用户模型；</li><li>产品技能熟练度。</li></ol><p>只提“批判性思维”而不提“深度思考”，是因为批判性思维不是特别依赖天赋，也是后天可以有效提升的，提升后也能有效提高输出决策的质量，所以适用于评估多数产品经理。具有很强同理心的人罕见，但面试的主要目的是把同理心差的人挑出来，这些人从事产品经理职业会使他和企业都越来越痛苦。考察用户模型，即考察候选人对他做过产品的用户模型的掌握程度，并由此判断他对人性常识和大众心理的认知程度。产品技能熟练度用于判断候选人的产品基础扎实程度，但一定程度上也依赖过往产品实践机会的质量，以此可以反推候选人的产品心、学习能力。与更偏天赋的洞察力相比，决策能力可经学习提高。</p><h3 id="潜力" tabindex="-1">潜力 <a class="header-anchor" href="#潜力" aria-label="Permalink to &quot;潜力&quot;">​</a></h3><p>产品经理的潜力是企业的长期价值，面试中主要判断三项:<a href="https://zhuanlan.zhihu.com/p/95577761" target="_blank" rel="noreferrer">^25</a></p><ol><li>自省(发现和承认自己的短处:学习、合作、雇用、回避)，是毫无疑问的第一潜力;</li><li>学习意愿和学习能力;</li><li>高成就动机。(短短的面试过程不能保证对潜力、性格、三观等有准确充分的判断，还需要在入职后的工作中持续判断。)</li></ol><p>自省，毫无疑问是产品经理的第一潜力。人一旦会自省，就有了进化能力，跟起点相近但不会自省的人相比，十年后的差别可能非常大。正确认识自己也是最艰难的事之一。任何产品做到最后，决定其上限的都是决策者的认知进化能力。在工作中，会自省的产品经理成长总是很快。所以，建议产品经理们要习惯于反思自己的认知、思考、行为，从发现的问题中正确认识自己的短处，然后通过学习、合作、雇用、回避等方法去改变。而面试选人，也应该关注优秀候选人的自省意识，如果遇到自省意识特别强或特别差的，就要区别对待。</p><p>产品经理不能光想不练，学习意愿和学习能力强的，普遍成长更快。另外，高成就动机也特别影响产品经理的成长性。所以，面试时，如果遇到这在两方面有优势的人，也应对其高看一眼。</p><h2 id="介绍一下你自己" tabindex="-1">介绍一下你自己 <a class="header-anchor" href="#介绍一下你自己" aria-label="Permalink to &quot;介绍一下你自己&quot;">​</a></h2><p>介绍一下自己的姓名，年龄、毕业院校，工作经历。简单的介绍，保持在三分钟以内，给面试官问问题的时间。</p><p>工作经历主要讲一些你牛逼的工作经历，例如：你加入XX公司以后，销售额增加了多少、用户翻了多少倍…这样一些。有些人工作经历比较多，3年跳了好几家公司，建议你合并一下，不然面试官会觉得你这个人没有定力，在其他家公司干的时间都不长，在我公司能干多久？</p><p>至于你的毕业院校牛逼的肯定要说出来，如果觉得学校不好，不好意思说那就不说吧。</p><p>只能简单说几句，几年职业生涯一笔带过，自我介绍不超过1分钟的。说明这个候选人在描述一个事情上是说不好的，不懂得组织文字和语句，这样工作时往往<strong>不能很好的表达自己的观点。</strong><a href="https://www.yuque.com/weis/pm/emr7ca" target="_blank" rel="noreferrer">^10</a></p><p>讲的和简历上写的不一样，或者漏掉重要的经历。这种候选人需要特别注意，后面要多询问，如果不是口误或者忘了的话，简历很可能就是过度包装的。</p><p>别写流水帐，让这些经历更好地为这次求职背书。<a href="https://www.zhihu.com/collection/618263456" target="_blank" rel="noreferrer">^23</a></p><h3 id="比例控制-22" tabindex="-1">比例控制 <a href="http://dadaghp.com/index/index/article_detail/id/670.html" target="_blank" rel="noreferrer">^22</a> <a class="header-anchor" href="#比例控制-22" aria-label="Permalink to &quot;比例控制 [^22]&quot;">​</a></h3><ul><li>应急毕业生（产助）：可塑性35%、沟通能力 25%、逻辑能力 25%、行业经历 5%、决策能力 5%、业绩体现 5%；</li><li>1到5年产品经验：行业经历 20%、业绩体现 20%，沟通能力 15%、逻辑能力15%、决策能力 15%、可塑性15%；</li><li>5年以上产品经验：决策能力 35%、业绩体现 30%、行业经历 25%、沟通能力 10%、逻辑能力 0%。</li></ul><h3 id="我自己的介绍" tabindex="-1">我自己的介绍 <a class="header-anchor" href="#我自己的介绍" aria-label="Permalink to &quot;我自己的介绍&quot;">​</a></h3><p>我叫蔡舒起，年龄23，现求职一份金融AI产品经理岗位。</p><ul><li>金融方面：2020届的山西大学金融学专业的毕业生，获得三好学生学业奖学金，拥有会计、证券、基金从业证书，毕业论文是用Python的Statsmodel库里的VAR模型完成的《中美股市的联动性分析》，提出百度股价被低估能上300USD的想法，实现后。现百度股票主打AI第一股重新去香港上市。</li><li>AI方面：大一参加数学建模了解了神经网络算法，后在网络金融课分享了鱼书的ppt，得知金融方面的非结构信息常用深度学习算法，之后阅读过二十几本人工智能相关书籍，在20年用4个月自学完了《动手学深度学习》预览版并动手翻译MXNet到PyTorch的GAN\\DCGAN，复现PyTorch、DJL等一系列深度学习移动端框架的Demo。</li><li>产品经理方面：在百度一面失败后，考虑到了百度开发者版的想法，与MXNet的开发者交流无人社区冷淡情况，学习十余本产品有关的书，并自行总结了AI产品经理的工作内容和技能要求，用Docker部署成《To be AI PM》书。</li></ul><h3 id="应届生-13" tabindex="-1">应届生 <a href="https://www.zhihu.com/question/57815929" target="_blank" rel="noreferrer">^13</a> <a class="header-anchor" href="#应届生-13" aria-label="Permalink to &quot;应届生 [^13]&quot;">​</a></h3><ol><li>对应届生做过的一件或几件重要的事深入询问，实习过的产品、参与过的项目、活动、学习、个人爱好等皆可。</li><li>看他对这件事的理解：各种选择的原因、各种收获或挫败的总结、各种问题的分析、做得好与不好的原因、其它可能性的判断等。</li><li>如果他能准确说清前因后果，差不多就有希望成长为合格 PM 了。如果还能有真知灼见，那么就有优秀 PM 的潜质，很可能他未来也能推动所负责的产品往前多走一步。</li></ol><h2 id="真正的选拔" tabindex="-1">真正的选拔 <a class="header-anchor" href="#真正的选拔" aria-label="Permalink to &quot;真正的选拔&quot;">​</a></h2><p>我真正想听的是这种问题：</p><ul><li>你过往经历里方向背景是B端还是C端？</li><li>你设计的系统处理业务是属于电商类？社区类还是文娱？</li></ul><p>这张图怎么用呢？举例来说如果一家公司要求学历为大专及以上，那么如果你在面试的自我介绍中<strong>直截了当的告诉面试官我毕业于某某大学</strong>，那么面试官心中这里就直接在给你加上了学历匹配的5分。</p><p><img src="'+t+'" alt="匹配阶梯"></p><p>根据上面六项做完匹配后，根据最终的得分我们可以将候选人直接分为这几类档：</p><p><img src="'+o+'" alt="候选人分档"></p><p>直观来说与其招到一个能把原型画到100分但是薪资相对于其他90分左右的产品提高了30%，对于企业来说是没有多少意义的。</p><p>反之如果在高层级产品上选对了人，<strong>他能在重大决策上有100分的判断</strong>，例如<strong>在直播还在百花齐放的时代，有人先转型涉足了短视频领域做出了抖音，虽然他的薪资成本提高了30%但是带来的意义是巨大的。</strong></p><p>因此在公司层面来说<strong>对执行层人员的选择更多是选合适，而不是一定要非常优秀。</strong></p><p>这里我把这种现象称之为<strong>低端饱和竞争</strong>。</p><p>所以大家在后面的产品发展道路上除了要去磨练自己的一般性技能外，还要去主动学习更高层次的产品经理所要掌握的技能，<strong>不要用战术上勤奋掩盖战略上懒惰。</strong></p><h3 id="战略" tabindex="-1">战略 <a class="header-anchor" href="#战略" aria-label="Permalink to &quot;战略&quot;">​</a></h3><h2 id="一是围绕他过去做过的某件事-一般是某个产品或某个功能-也可以是其他-进行深入提问。" tabindex="-1">一是围绕他过去做过的某件事（一般是某个产品或某个功能，也可以是其他）进行深入提问。 <a class="header-anchor" href="#一是围绕他过去做过的某件事-一般是某个产品或某个功能-也可以是其他-进行深入提问。" aria-label="Permalink to &quot;一是围绕他过去做过的某件事（一般是某个产品或某个功能，也可以是其他）进行深入提问。&quot;">​</a></h2><ul><li>你开始为什么要做这个东西？</li><li>你是怎么想到的？</li><li>针对以后的情况你考虑了哪些方面和做了些什么？</li><li>开始做的过程中遇到了什么问题？</li><li>你是怎么解决的？发现了什么？</li><li>什么东西和原来理解的不一样了？</li><li>又发现了哪些相关的洞察，你和外部市场上的其他人对其认知不一样？</li><li>在迭代过程中又是怎么做的？</li><li>你现在对这件事情的认知有什么变化？</li><li>如果再回到当初，你还会做什么？</li></ul><p>TODO: <a href="https://www.infoq.cn/article/kkfAX67GAlsRSP65JvBy" target="_blank" rel="noreferrer">https://www.infoq.cn/article/kkfAX67GAlsRSP65JvBy</a></p><h2 id="为什么想做产品经理-2" tabindex="-1">为什么想做产品经理 <a href="http://www.woshipm.com/zhichang/315041.html" target="_blank" rel="noreferrer">^2</a> <a class="header-anchor" href="#为什么想做产品经理-2" aria-label="Permalink to &quot;为什么想做产品经理 [^2]&quot;">​</a></h2><ul><li>兴趣爱好：我热爱AI，相信AI的认知（DL）与决策能力（RL）能极大提升生产力，帮助人们，比如我了解到美团用语音机器人联系人员复工，解放了很多重复的电话员的工作。而且更关心技术实际的社会经济作用，也就是“场景驱动技术”，去关注最需要的业务，技术研发不是为了炫技也没必要一味拿着钉子找榔头。</li><li>能力匹配：我个人有提到百度开发版的主意，这个想法来自于我身为程序员toC用户本身想法而来，我也了解到就算百度员工也用谷歌。那不管从个人效率，公司战略，乃至国家安全角度，这个产品都是非常重要的</li><li>职业规划<a href="https://www.bilibili.com/video/BV1UK4y1f7kK?from=search&amp;seid=11977543152973696126" target="_blank" rel="noreferrer">^17</a>：目前近三五年是想在产品经理岗上将AI技术赋能给更多企业与个人，尤其是金融和体育方向，这都是我比较热爱和了解的方向。</li></ul><h2 id="你用了我们的产品么-对我们的产品有啥建议" tabindex="-1">你用了我们的产品么？对我们的产品有啥建议？ <a class="header-anchor" href="#你用了我们的产品么-对我们的产品有啥建议" aria-label="Permalink to &quot;你用了我们的产品么？对我们的产品有啥建议？&quot;">​</a></h2><p>正确回答：（先吹嘘一番）公司做的这个业务市场规模很大，很有前景，而且我们公司是做的比较好的，产品体验也不错，尤其XX地方，设计的很好，用户体验很棒，但个人认为在一些细节上还有优化的空间，XX功能如果XX做的话会更好一些。</p><p>“你对我们公司的产品有什么看法？”一个合格的产品经理会<strong>避其锋芒</strong>，委婉地表达对公司的敬意、对行业的熟悉、对竞品的研究，而不会感觉终于有了一个当面吐槽的机会，一股脑地说出很多意见或者建议，哪怕这些是正确的，也会让别人觉得不舒服。你在外界看到的信息，在公司内部的员工肯定已经看过了，并且研究过了，因为这是他们的工作，所以他们不太可能认可你的意见。因此，你千万要沉住气，要保持合理的谦虚。 <a href="https://weread.qq.com/web/reader/46532b707210fc4f465d044kb6d32b90216b6d767d2f0dc" target="_blank" rel="noreferrer">^12</a></p><h2 id="谈谈竞品" tabindex="-1">谈谈竞品？ <a class="header-anchor" href="#谈谈竞品" aria-label="Permalink to &quot;谈谈竞品？&quot;">​</a></h2><p>既然是产品面试，在已知所在岗位要面向的产品时，竞品分析报告必须得提前做好！这里我也是早就做了准备，主要是针对腾讯云/百度云/阿里云做了个分析（产品功能/推广/运营模式/商业化）。</p><p>分析比较两款同类产品的优劣/特点，或是让你下载他们公司的产品说一下意见和使用感受，这点可以在接到面试通知的时候就在网上查阅了解下，然后提前准备好。 <a href="https://www.zhihu.com/search?type=content&amp;q=%E4%BA%A7%E5%93%81+%E7%AC%94%E8%AF%95" target="_blank" rel="noreferrer">^16</a></p><h2 id="你最喜欢的产品是什么-3" tabindex="-1">你最喜欢的产品是什么？<a href="http://www.woshipm.com/pmd/2891945.html" target="_blank" rel="noreferrer">^3</a> <a class="header-anchor" href="#你最喜欢的产品是什么-3" aria-label="Permalink to &quot;你最喜欢的产品是什么？[^3]&quot;">​</a></h2><p>用户体验的五个层次出发，显得有条理：战略、范围、结构、框架、表现</p><p>比如从战略层，产品的核心是解决了什么用户痛点，这个市场规模能有多大。那么你回答的信息整合和用户调性，本质上都是它的产品定位以及配套的业务范围，也许是整个团队需要努力保持的核心竞争力。</p><p>结构方面，关注流和推荐流的层级设计，比如抖音是推荐主导，微博是关注主导，也能体现产品设计的侧重点。</p><p>构架和表现层，其实移动互联网时代的交互已经很久没有大的变化了，所以大多数正常产品挑不出大毛病，偶尔有一些细节彩蛋就会让人很惊喜，比如你说的blabla……”</p><h3 id="列出你觉得好的1个app-为什么" tabindex="-1">列出你觉得好的1个APP，为什么？ <a class="header-anchor" href="#列出你觉得好的1个app-为什么" aria-label="Permalink to &quot;列出你觉得好的1个APP，为什么？&quot;">​</a></h3><ul><li>产品名称：keep<a href="https://zhuanlan.zhihu.com/p/391687873" target="_blank" rel="noreferrer">^27</a></li><li>产品定位：为用户制定专业的健身教程</li><li>目标用户：没时间去健身房的人，想要定制专业课程的人，偶尔运动的人。</li><li>核心痛点：短视频教程，专业的系列课程，健身达人分享</li><li>需求场景： <ol><li>上班族没有时间去健身房，下班以后使用keep来一套专业的健身训练。</li><li>身体某些部位感觉不健康，或者容易疲劳，寻找针对性的训练课程，来锻炼这个部位。</li><li>去健身房不想花钱找专业的健身教练，使用keep来制定专业的健身房训练课程。</li><li>自己练还不够，在keep上寻找达人，通过达人的健身分享来激励和锻炼自己。</li></ol></li></ul><h2 id="问清题目-4" tabindex="-1">问清题目<a href="https://zhuanlan.zhihu.com/p/108911948#%E4%B8%80%E4%B8%AA%E9%9D%9E%E5%B8%B8%E7%AE%80%E5%8D%95%E7%9A%84%E4%BE%8B%E5%AD%90" target="_blank" rel="noreferrer">^4</a> <a class="header-anchor" href="#问清题目-4" aria-label="Permalink to &quot;问清题目[^4]&quot;">​</a></h2><p>许多面试官在面试的时候，会故意先抛出一个模糊的问题。实际上，他们希望面试者能够经过一些询问理解问题。在这个过程中，面试者能够展现出自己对问题的分析能力以及沟通的能力。前者的重要性参见编程珠玑第一章：明确问题，战役就成功了90%。后者的重要性在于，问清题目的这个交流过程与面试者入职之后与同事讨论问题的形式非常类似。显而易见，一个能够很难沟通的面试者也很难成为一个很好沟通的同事。</p><h2 id="面试的坑-21" tabindex="-1">面试的坑 <a href="https://t.qidianla.com/934094.html" target="_blank" rel="noreferrer">^21</a> <a class="header-anchor" href="#面试的坑-21" aria-label="Permalink to &quot;面试的坑 [^21]&quot;">​</a></h2><p>虽然我们是小白，在很多问题的想法和见解上都不成熟，但只要不是特别离谱的，当面试官质疑的时候，都不要那么快推翻自己的看法，这时候考验的是产品经理的<strong>抗压能力和资源争取能力</strong>，太容易妥协毫无自己想法很快就掉进面试官的挖的坑里了。</p><h2 id="to-b的产品-跟to-c-的产品-在设计产品过程中有什么不同-5" tabindex="-1">To B的产品，跟To c 的产品，在设计产品过程中有什么不同？<a href="https://zhuanlan.zhihu.com/p/33524676" target="_blank" rel="noreferrer">^5</a> <a class="header-anchor" href="#to-b的产品-跟to-c-的产品-在设计产品过程中有什么不同-5" aria-label="Permalink to &quot;To B的产品，跟To c 的产品，在设计产品过程中有什么不同？[^5]&quot;">​</a></h2><p>toB 公司产品要保证的是交付给客户的解决方案的结果和质量。<a href="http://www.ramywu.com/work/2018/04/09/Get-Ready-For-AI-PM/" target="_blank" rel="noreferrer">^8</a>所以 AI PM 在推动产品落地的过程中，需要各种团队协作、跨部门沟通、向上汇报等，因为工作目标是交付项目，在项目管理本身有很多蛮内隐知识在里面够学的了。</p><p>对2C平台来说，每个阶段的侧重点是不同的，前期更注重日活，后期看GMV。<a href="https://m.k.sohu.com/d/495625828?channelId=1&amp;page=1" target="_blank" rel="noreferrer">^7</a></p><h2 id="常见问题-15" tabindex="-1">常见问题 <a href="https://zhuanlan.zhihu.com/p/350981809" target="_blank" rel="noreferrer">^15</a> <a class="header-anchor" href="#常见问题-15" aria-label="Permalink to &quot;常见问题 [^15]&quot;">​</a></h2><ul><li>请描述下你和客户沟通的技巧</li><li>请描述一个和客户沟通后，对产品理解加深的例子</li><li>怎么判断研发给你的排期是否合理</li><li>请描述下你之前负责的一个产品的产品规划</li><li>你目前所在的行业的市场规模有多大？测算逻辑是什么？</li><li>你们公司目前的市场占有率是多大？测算逻辑是什么？</li><li>产品做前期市场推广时，如何找高价值客户的？</li><li>请简述下你对行业未来发展趋势的看法</li><li>你目前负责产品的人均产出是多少？和公司其他产品比较呢？</li><li>你对XX算法的了解有多少？可以简单介绍下这方面的技术</li><li>你负责产品的主要竞品有哪些？主要优劣势？</li><li>请描述一个你成功/失败的项目和原因分析</li><li>如果让你做xx产品，你会怎么做？回复建议：从产品架构、功能设计、测评、资源层面做简单阐述。<a href="https://zhuanlan.zhihu.com/p/368667240" target="_blank" rel="noreferrer">^24</a></li></ul><h2 id="自提问题" tabindex="-1">自提问题： <a class="header-anchor" href="#自提问题" aria-label="Permalink to &quot;自提问题：&quot;">​</a></h2><ul><li>为何前面有快消产品经理所注重的品牌产品经理的内容？</li><li>什么时候能够得到反馈？</li><li>如能入职贵司，您希望在三个月，半年内甚至一年内，对我工作成绩有怎么期望？ <a href="https://zhuanlan.zhihu.com/p/33395387" target="_blank" rel="noreferrer">^14</a></li><li>Axure卡死的情况？比如点了代理之后代理界面在缩略图的弹出来但实际不显示，只能退出。。</li></ul><p>业务方面：<a href="https://shimo.im/docs/vyCrK3rQQ6KC9Ryp/read" target="_blank" rel="noreferrer">^18</a></p><ul><li>工作的具体内容是什么，公司对这个岗位的定位是什么？（JD的文字一般都不多，何况还会有些包装的情况，所以了解清楚具体要做的工作内容非常重要，避免入职后才发现与预期不符）</li><li>成为你心目中理想的产品经理候选人需要具备什么条件？</li><li>产品去年的数据表现如何，如果是新产品，是谁牵着立项的，<strong>目前的进展如何了</strong></li><li>其他对业务好奇的问题</li></ul><p>团队方面：</p><ul><li>要了解目标岗位因何设立，是团队扩张新设的岗位，还是之前的人离职了，前面的人为什么离职</li><li>汇报线是什么样的，问清楚我们的汇报对象，也就是直接上级。通过询问，了解上级在公司的角色是什么，他的风格、要求是什么样的，对下属的预期，甚至直接问出公司希望你带来什么样的价值。这些直接的答案都可以加深你对公司的了解程度。<a href="https://www.zhihu.com/question/350672843/answer/1997174430" target="_blank" rel="noreferrer">^26</a></li><li><strong>整个团队有多少人，产品团队有多少人，大概有哪些分工，与其他部门的合作关系，未来会达到什么样的规模</strong>(一面的时候问面试官部门和具体业务，二面前进行充分准备和了解呐。<a href="https://zhuanlan.zhihu.com/p/87293782" target="_blank" rel="noreferrer">^19</a>)</li></ul><p>leader方面：</p><ul><li>目前负责的工作内容</li><li><strong>管理风格以及对下属的期待</strong></li><li>历史成绩和择业原因</li><li>其他对leader好奇的内容</li><li>你觉得在这里做产品经理最有挑战性的是什么？<a href="https://www.jianshu.com/p/09e7ae756bc6" target="_blank" rel="noreferrer">^20</a></li></ul><p>回报方面：<a href="https://github.com/zhuangyin8/zhuangyin8.github.io/issues/137#issuecomment-913961326" target="_blank" rel="noreferrer">^28</a></p><ul><li>一年几次调薪考核、具体时间？</li><li>什么薪酬架构，底薪发多少个月，有否绩效奖金、比例多少？</li><li>绩效和年终奖具体怎么算，几月份发？</li><li>五险一金的缴纳基数是多少，跟工资一样吗？</li><li>有否其他福利，餐补、车贴、节假日补贴、补充医疗保险？</li></ul>',81)])])}const m=e(h,[["render",n]]);export{b as __pageData,m as default};
